/**
 * Expands the biography and timeline of the 15 designers from
 * seed-influential-designers.ts to match the depth of the Arne Jacobsen
 * profile (full-length biography, a long, granular career timeline).
 * Leaves quote, in_focus and similar_designers untouched.
 *
 *   npx medusa exec ./src/scripts/expand-influential-designers.ts
 */
import type { ExecArgs } from "@medusajs/framework/types"
import { DESIGNER_MODULE } from "../modules/designer"
import type DesignerModuleService from "../modules/designer/service"

type TimelineEntry = { date: string; title: string; subtitle: string; description: string }

type Expansion = { slug: string; biography: string; timeline: TimelineEntry[] }

