export default async function expandInfluentialDesigners({ container }: ExecArgs) {
  const designerModuleService: DesignerModuleService = container.resolve(DESIGNER_MODULE)

  for (const expansion of EXPANSIONS) {
    const [designer] = await designerModuleService.listDesigners({ slug: expansion.slug })
    if (!designer) {
      console.warn(`Skipping ${expansion.slug}: designer not found`)
      continue
    }

    await designerModuleService.updateDesigners({
      id: designer.id,
      biography: expansion.biography,
      timeline: { entries: expansion.timeline },
    })
    console.log(`Expanded ${expansion.slug}: bio ${expansion.biography.length} chars, ${expansion.timeline.length} timeline entries`)
  }

  console.log(`Done. Expanded ${EXPANSIONS.length} designer(s).`)
}
